function buyLocked(
        Lien calldata lien,
        SellOffer calldata offer,
        bytes calldata signature
    ) public validateLien(lien, offer.lienId) lienIsActive(lien) {
        (uint256 priceAfterFees, uint256 debt) = _buyLocked(lien, offer, signature);

        /* Send token to buyer. */
        lien.collection.safeTransferFrom(address(this), msg.sender, lien.tokenId);

        /* Repay lender. */
        _POOL.transferFrom(msg.sender, lien.lender, debt);

        /* Send surplus to borrower. */
        unchecked {
            _POOL.transferFrom(msg.sender, lien.borrower, priceAfterFees - debt);
        }
    }

function buyLockedETH(
        Lien calldata lien,
        SellOffer calldata offer,
        bytes calldata signature
    ) external payable {
        _POOL.deposit{ value: msg.value }(msg.sender);
        return buyLocked(lien, offer, signature);
    }

function buyToBorrow(
        LoanOffer calldata offer,
        bytes calldata signature,
        uint256 loanAmount,
        ExecutionV1 calldata execution
    ) public returns (uint256 lienId) {
        if (execution.makerOrder.order.trader == address(this)) {
            revert Unauthorized();
        }
        if (offer.auctionDuration > _MAX_AUCTION_DURATION) {
            revert InvalidAuctionDuration();
        }

        uint256 collateralTokenId = execution.makerOrder.order.tokenId;
        uint256 price = execution.makerOrder.order.price;

        /* Create lien. */
        Lien memory lien = Lien({
            lender: offer.lender,
            borrower: msg.sender,
            collection: offer.collection,
            tokenId: collateralTokenId,
            amount: loanAmount,
            startTime: block.timestamp,
            rate: offer.rate,
            auctionStartBlock: 0,
            auctionDuration: offer.auctionDuration
        });
        unchecked {
            liens[lienId = _nextLienId++] = keccak256(abi.encode(lien));
        }

        /* Take the loan offer. */
        _takeLoanOffer(offer, signature, lien, lienId);

        /* Create the buy side order coming from Blend. */
        Helpers.executeTakeAsk(
            offer,
            execution,
            loanAmount,
            collateralTokenId,
            price,
            _POOL,
            _EXCHANGE,
            _SELL_MATCHING_POLICY
        );
    }

function buyToBorrowETH(
        LoanOffer calldata offer,
        bytes calldata signature,
        uint256 loanAmount,
        ExecutionV1 calldata execution
    ) external payable returns (uint256 lienId) {
        _POOL.deposit{ value: msg.value }(msg.sender);
        return buyToBorrow(offer, signature, loanAmount, execution);
    }

function buyToBorrowLocked(
        Lien calldata lien,
        SellInput calldata sellInput,
        LoanInput calldata loanInput,
        uint256 loanAmount
    )
        public
        validateLien(lien, sellInput.offer.lienId)
        lienIsActive(lien)
        returns (uint256 lienId)
    {
        if (lien.collection != loanInput.offer.collection) {
            revert CollectionsDoNotMatch();
        }

        (uint256 priceAfterFees, uint256 debt) = _buyLocked(
            lien,
            sellInput.offer,
            sellInput.signature
        );

        lienId = _borrow(loanInput.offer, loanInput.signature, loanAmount, lien.tokenId);

        /* Transfer funds. */
        /* Need to repay the original loan and payout any surplus from the sell or loan funds. */
        if (loanAmount < debt) {
            /* loanAmount < debt < priceAfterFees */

            /* Repay loan with funds from new lender to old lender. */
            _POOL.transferFrom(loanInput.offer.lender, lien.lender, loanAmount); // doesn't cover debt

            unchecked {
                /* Supplement difference from new borrower. */
                _POOL.transferFrom(msg.sender, lien.lender, debt - loanAmount); // cover rest of debt

                /* Send rest of sell funds to borrower. */
                _POOL.transferFrom(msg.sender, sellInput.offer.borrower, priceAfterFees - debt);
            }
        } else if (loanAmount < priceAfterFees) {
            /* debt < loanAmount < priceAfterFees */

            /* Repay loan with funds from new lender to old lender. */
            _POOL.transferFrom(loanInput.offer.lender, lien.lender, debt);

            unchecked {
                /* Send rest of loan from new lender to old borrower. */
                _POOL.transferFrom(
                    loanInput.offer.lender,
                    sellInput.offer.borrower,
                    loanAmount - debt
                );

                /* Send rest of sell funds from new borrower to old borrower. */
                _POOL.transferFrom(
                    msg.sender,
                    sellInput.offer.borrower,
                    priceAfterFees - loanAmount
                );
            }
        } else {
            /* debt < priceAfterFees < loanAmount */

            /* Repay loan with funds from new lender to old lender. */
            _POOL.transferFrom(loanInput.offer.lender, lien.lender, debt);

            unchecked {
                /* Send rest of sell funds from new lender to old borrower. */
                _POOL.transferFrom(
                    loanInput.offer.lender,
                    sellInput.offer.borrower,
                    priceAfterFees - debt
                );

                /* Send rest of loan from new lender to new borrower. */
                _POOL.transferFrom(loanInput.offer.lender, msg.sender, loanAmount - priceAfterFees);
            }
        }
    }

function buyToBorrowLockedETH(
        Lien calldata lien,
        SellInput calldata sellInput,
        LoanInput calldata loanInput,
        uint256 loanAmount
    ) external payable returns (uint256 lienId) {
        _POOL.deposit{ value: msg.value }(msg.sender);
        return buyToBorrowLocked(lien, sellInput, loanInput, loanAmount);
    }

function buyToBorrowV2(
        LoanOffer calldata offer,
        bytes calldata signature,
        uint256 loanAmount,
        AskExecutionV2 calldata execution
    ) public returns (uint256 lienId) {
        if (offer.auctionDuration > _MAX_AUCTION_DURATION) {
            revert InvalidAuctionDuration();
        }

        uint256 collateralTokenId = execution.listing.tokenId;
        uint256 price = execution.listing.price;

        /* Create lien. */
        Lien memory lien = Lien({
            lender: offer.lender,
            borrower: msg.sender,
            collection: offer.collection,
            tokenId: collateralTokenId,
            amount: loanAmount,
            startTime: block.timestamp,
            rate: offer.rate,
            auctionStartBlock: 0,
            auctionDuration: offer.auctionDuration
        });
        unchecked {
            liens[lienId = _nextLienId++] = keccak256(abi.encode(lien));
        }

        /* Take the loan offer. */
        _takeLoanOffer(offer, signature, lien, lienId);

        /* Execute order using ETH currently in contract. */
        Helpers.executeTakeAskV2(
            offer,
            execution,
            loanAmount,
            collateralTokenId,
            price,
            _POOL,
            _EXCHANGE_V2
        );
    }

function buyToBorrowV2ETH(
        LoanOffer calldata offer,
        bytes calldata signature,
        uint256 loanAmount,
        AskExecutionV2 calldata execution
    ) external payable returns (uint256 lienId) {
        _POOL.deposit{ value: msg.value }(msg.sender);
        return buyToBorrowV2(offer, signature, loanAmount, execution);
    }

function takeBid(
        Lien calldata lien,
        uint256 lienId,
        ExecutionV1 calldata execution
    ) external validateLien(lien, lienId) lienIsActive(lien) {
        if (execution.makerOrder.order.trader == address(this) || msg.sender != lien.borrower) {
            revert Unauthorized();
        }

        /* Repay loan with funds received from the sale. */
        uint256 debt = _repay(lien, lienId);

        Helpers.executeTakeBid(
            lien,
            lienId,
            execution,
            debt,
            _POOL,
            _EXCHANGE,
            _DELEGATE,
            _BID_MATCHING_POLICY
        );
    }

function takeBidV2(
        Lien calldata lien,
        uint256 lienId,
        BidExecutionV2 calldata execution
    ) external validateLien(lien, lienId) lienIsActive(lien) {
        if (msg.sender != lien.borrower) {
            revert Unauthorized();
        }

        /* Repay loan with funds received from the sale. */
        uint256 debt = _repay(lien, lienId);

        Helpers.executeTakeBidV2(lien, execution, debt, _POOL, _EXCHANGE_V2, _DELEGATE_V2);
    }

function cancelOffer(uint256 salt) external {
        _cancelOffer(msg.sender, salt);
    }

function cancelOffers(uint256[] calldata salts) external {
        uint256 saltsLength = salts.length;
        for (uint256 i; i < saltsLength; ) {
            _cancelOffer(msg.sender, salts[i]);
            unchecked {
                ++i;
            }
        }
    }

function _buyLocked(
        Lien calldata lien,
        SellOffer calldata offer,
        bytes calldata signature
    ) internal returns (uint256 priceAfterFees, uint256 debt) {
        if (lien.borrower != offer.borrower) {
            revert Unauthorized();
        }

        priceAfterFees = _takeSellOffer(offer, signature);

        /* Repay loan with funds received from the sale. */
        debt = _repay(lien, offer.lienId);
        if (priceAfterFees < debt) {
            revert InvalidRepayment();
        }

        emit BuyLocked(
            offer.lienId,
            address(lien.collection),
            msg.sender,
            lien.borrower,
            lien.tokenId
        );
    }

function _takeSellOffer(
        SellOffer calldata sellOffer,
        bytes calldata sellSignature
    ) internal returns (uint256 priceAfterFees) {
        _validateOffer(
            _hashSellOffer(sellOffer),
            sellOffer.borrower,
            sellOffer.oracle,
            sellSignature,
            sellOffer.expirationTime,
            sellOffer.salt
        );

        /* Mark the sell offer as fulfilled. */
        cancelledOrFulfilled[sellOffer.borrower][sellOffer.salt] = 1;

        /* Transfer fees. */
        uint256 totalFees = _transferFees(sellOffer.fees, msg.sender, sellOffer.price);
        unchecked {
            priceAfterFees = sellOffer.price - totalFees;
        }
    }

function _borrow(
        LoanOffer calldata offer,
        bytes calldata signature,
        uint256 loanAmount,
        uint256 collateralTokenId
    ) internal returns (uint256 lienId) {
        if (offer.auctionDuration > _MAX_AUCTION_DURATION) {
            revert InvalidAuctionDuration();
        }

        Lien memory lien = Lien({
            lender: offer.lender,
            borrower: msg.sender,
            collection: offer.collection,
            tokenId: collateralTokenId,
            amount: loanAmount,
            startTime: block.timestamp,
            rate: offer.rate,
            auctionStartBlock: 0,
            auctionDuration: offer.auctionDuration
        });

        /* Create lien. */
        unchecked {
            liens[lienId = _nextLienId++] = keccak256(abi.encode(lien));
        }

        /* Take the loan offer. */
        _takeLoanOffer(offer, signature, lien, lienId);
    }

function _takeLoanOffer(
        LoanOffer calldata offer,
        bytes calldata signature,
        Lien memory lien,
        uint256 lienId
    ) internal {
        bytes32 hash = _hashOffer(offer);

        _validateOffer(
            hash,
            offer.lender,
            offer.oracle,
            signature,
            offer.expirationTime,
            offer.salt
        );

        if (offer.rate > _LIQUIDATION_THRESHOLD) {
            revert RateTooHigh();
        }
        if (lien.amount > offer.maxAmount || lien.amount < offer.minAmount) {
            revert InvalidLoan();
        }
        uint256 _amountTaken = amountTaken[hash];
        if (offer.totalAmount - _amountTaken < lien.amount) {
            revert InsufficientOffer();
        }

        unchecked {
            amountTaken[hash] = _amountTaken + lien.amount;
        }

        emit LoanOfferTaken(
            hash,
            lienId,
            address(offer.collection),
            lien.lender,
            lien.borrower,
            lien.amount,
            lien.rate,
            lien.tokenId,
            lien.auctionDuration
        );
    }

function _verifyOfferAuthorization(
        bytes32 offerHash,
        address lender,
        address oracle,
        bytes calldata signature
    ) internal view {
        bytes32 hashToSign = _hashToSign(offerHash);
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 0x20))
            v := shr(248, calldataload(add(signature.offset, 0x40)))
        }
        _verify(lender, hashToSign, v, r, s);

        /* Verify oracle signature if required. */
        if (oracle != address(0)) {
            uint256 blockNumber;
            assembly {
                r := calldataload(add(signature.offset, 0x41))
                s := calldataload(add(signature.offset, 0x61))
                v := shr(248, calldataload(add(signature.offset, 0x81)))
                blockNumber := calldataload(add(signature.offset, 0x82))
            }
            if (oracles[oracle] == 0) {
                revert UnauthorizedOracle();
            }
            if (blockNumber + blockRange < block.number) {
                revert SignatureExpired();
            }

            hashToSign = _hashToSignOracle(offerHash, blockNumber);
            _verify(oracle, hashToSign, v, r, s);
        }
    }

function _validateOffer(
        bytes32 offerHash,
        address signer,
        address oracle,
        bytes calldata signature,
        uint256 expirationTime,
        uint256 salt
    ) internal view {
        _verifyOfferAuthorization(offerHash, signer, oracle, signature);

        if (expirationTime < block.timestamp) {
            revert OfferExpired();
        }
        if (cancelledOrFulfilled[signer][salt] == 1) {
            revert OfferUnavailable();
        }
    }

function _transferFees(
        Fee[] calldata fees,
        address from,
        uint256 price
    ) internal returns (uint256 totalFee) {
        uint256 feesLength = fees.length;
        for (uint256 i = 0; i < feesLength; ) {
            uint256 fee = (price * fees[i].rate) / _BASIS_POINTS;
            _POOL.transferFrom(from, fees[i].recipient, fee);
            totalFee += fee;
            unchecked {
                ++i;
            }
        }
        if (totalFee > price) {
            revert FeesTooHigh();
        }
    }

function executeTakeAsk(
        LoanOffer calldata offer,
        ExecutionV1 calldata execution,
        uint256 loanAmount,
        uint256 collateralTokenId,
        uint256 price,
        IBlurPool pool,
        IExchange exchange,
        address matchingPolicy
    ) external {
        /* Transfer funds. */
        /* Need to retrieve the ETH to fund the marketplace execution. */
        if (loanAmount < price) {
            /* Take funds from lender. */
            pool.withdrawFrom(offer.lender, address(this), loanAmount);

            /* Supplement difference from borrower. */
            unchecked {
                pool.withdrawFrom(msg.sender, address(this), price - loanAmount);
            }
        } else {
            /* Take funds from lender. */
            pool.withdrawFrom(offer.lender, address(this), price);

            /* Send surplus to borrower. */
            unchecked {
                pool.transferFrom(offer.lender, msg.sender, loanAmount - price);
            }
        }

        OrderV1 memory buyOrder = OrderV1({
            trader: address(this),
            side: Side.Buy,
            matchingPolicy: matchingPolicy,
            collection: address(offer.collection),
            tokenId: collateralTokenId,
            amount: 1,
            paymentToken: address(0),
            price: price,
            listingTime: execution.makerOrder.order.listingTime + 1, // listingTime determines maker/taker
            expirationTime: type(uint256).max,
            fees: new Fee[](0),
            salt: uint160(execution.makerOrder.order.trader), // prevent reused order hash
            extraParams: "\x01" // require oracle signature
        });
        Input memory buy = Input({
            order: buyOrder,
            v: 0,
            r: bytes32(0),
            s: bytes32(0),
            extraSignature: execution.extraSignature,
            signatureVersion: SignatureVersion.Single,
            blockNumber: execution.blockNumber
        });

        /* Execute order using ETH currently in contract. */
        exchange.execute{ value: price }(execution.makerOrder, buy);
    }

function executeTakeBid(
        Lien calldata lien,
        uint256 lienId,
        ExecutionV1 calldata execution,
        uint256 debt,
        IBlurPool pool,
        IExchange exchange,
        address delegate,
        address matchingPolicy
    ) external {
        /* Create sell side order from Blend. */
        OrderV1 memory sellOrder = OrderV1({
            trader: address(this),
            side: Side.Sell,
            matchingPolicy: matchingPolicy,
            collection: address(lien.collection),
            tokenId: lien.tokenId,
            amount: 1,
            paymentToken: address(pool),
            price: execution.makerOrder.order.price,
            listingTime: execution.makerOrder.order.listingTime + 1, // listingTime determines maker/taker
            expirationTime: type(uint256).max,
            fees: new Fee[](0),
            salt: lienId, // prevent reused order hash
            extraParams: "\x01" // require oracle signature
        });
        Input memory sell = Input({
            order: sellOrder,
            v: 0,
            r: bytes32(0),
            s: bytes32(0),
            extraSignature: execution.extraSignature,
            signatureVersion: SignatureVersion.Single,
            blockNumber: execution.blockNumber
        });

        /* Execute marketplace order. */
        uint256 balanceBefore = pool.balanceOf(address(this));
        lien.collection.approve(delegate, lien.tokenId);
        exchange.execute(sell, execution.makerOrder);

        /* Determine the funds received from the sale (after fees). */
        uint256 amountReceivedFromSale = pool.balanceOf(address(this)) - balanceBefore;
        if (amountReceivedFromSale < debt) {
            revert InvalidRepayment();
        }

        /* Repay lender. */
        pool.transferFrom(address(this), lien.lender, debt);

        /* Send surplus to borrower. */
        unchecked {
            pool.transferFrom(address(this), lien.borrower, amountReceivedFromSale - debt);
        }
    }

function executeTakeAskV2(
        LoanOffer calldata offer, 
        AskExecutionV2 calldata execution,
        uint256 loanAmount,
        uint256 collateralTokenId,
        uint256 price,
        IBlurPool pool,
        IExchangeV2 exchangeV2
    ) external {
        OrderV2 calldata order = execution.order;
        if (address(offer.collection) != order.collection || order.assetType != AssetType.ERC721) {
            revert InvalidExecution();
        }

        /* Transfer funds. */
        /* Need to retrieve the ETH to fund the marketplace execution. */
        if (loanAmount < price) {
            /* Take funds from lender. */
            pool.withdrawFrom(offer.lender, address(this), loanAmount);

            /* Supplement difference from borrower. */
            unchecked {
                pool.withdrawFrom(msg.sender, address(this), price - loanAmount);
            }
        } else {
            /* Take funds from lender. */
            pool.withdrawFrom(offer.lender, address(this), price);

            /* Send surplus to borrower. */
            unchecked {
                pool.transferFrom(offer.lender, msg.sender, loanAmount - price);
            }
        }

        TakeAskSingle memory execute = TakeAskSingle({
            order: execution.order,
            exchange: Exchange({
                index: 0,
                proof: execution.proof,
                listing: Listing({
                    index: execution.listing.index,
                    tokenId: collateralTokenId,
                    amount: 1,
                    price: price
                }),
                taker: Taker({ tokenId: collateralTokenId, amount: 1 })
            }),
            takerFee: FeeRate(address(0), 0),
            signature: execution.signature,
            tokenRecipient: address(this)
        });
        exchangeV2.takeAskSingle{ value: price }(execute, execution.oracleSignature);
    }

function executeTakeBidV2(
        Lien calldata lien,
        BidExecutionV2 calldata execution,
        uint256 debt,
        IBlurPool pool,
        IExchangeV2 exchangeV2,
        address delegateV2
    ) external {
        OrderV2 calldata order = execution.order;
        if (address(lien.collection) != order.collection || order.assetType != AssetType.ERC721) {
            revert InvalidExecution();
        }

        uint256 balanceBefore = pool.balanceOf(address(this));

        TakeBidSingle memory execute = TakeBidSingle({
            order: execution.order,
            exchange: Exchange({
                index: 0,
                proof: execution.proof,
                listing: execution.listing,
                taker: Taker({ tokenId: lien.tokenId, amount: 1 })
            }),
            takerFee: FeeRate(address(0), 0),
            signature: execution.signature
        });

        /* Execute marketplace order. */
        lien.collection.approve(delegateV2, lien.tokenId);
        exchangeV2.takeBidSingle(execute, execution.oracleSignature);

        /* Determine the funds received from the sale (after fees). */
        uint256 amountReceivedFromSale = pool.balanceOf(address(this)) - balanceBefore;
        if (amountReceivedFromSale < debt) {
            revert InvalidRepayment();
        }

        /* Repay lender. */
        pool.transferFrom(address(this), lien.lender, debt);

        /* Send surplus to borrower. */
        unchecked {
            pool.transferFrom(address(this), lien.borrower, amountReceivedFromSale - debt);
        }
    }

function _cancelOffer(address user, uint256 salt) private {
        cancelledOrFulfilled[user][salt] = 1;
        emit OfferCancelled(user, salt);
    }

function accruedInterest() external onlyProxy {
        _accruedInterest();
    }

function afterSwap(uint256 ftReserve, uint256 xtReserve, int256 deltaFt, int256 deltaXt)
        external
        virtual
        override
        whenNotPaused
    {
        _delegateCall(
            abi.encodeCall(IOrderManagerV2.afterSwap, (IERC20(asset()), ftReserve, xtReserve, deltaFt, deltaXt))
        );
    }

function afterSwap(IERC20 asset, uint256 ftReserve, uint256 xtReserve, int256 deltaFt, int256 deltaXt)
        external
        onlyProxy
    {
        address orderAddress = msg.sender;
        /// @dev Check if the order is valid
        uint256 maturity = _orderMaturityMapping[orderAddress];
        require(maturity != 0, VaultErrors.UnauthorizedOrder(orderAddress));

        /// @dev Calculate interest from last update time to now
        _accruedInterest();

        /// @dev If ft increases, interest increases, and if ft decreases,
        ///  interest decreases. Update the expected annualized return based on the change
        uint256 ftChanges;

        if (deltaFt > 0) {
            ftChanges = uint256(deltaFt) * Constants.DECIMAL_BASE_SQ;
            _totalFt += ftChanges;
            uint256 deltaAnnualizedInterest = (ftChanges * 365 days) / (maturity - block.timestamp);

            _maturityToInterest[maturity.toUint64()] += deltaAnnualizedInterest;

            _annualizedInterest += deltaAnnualizedInterest;

            /// @dev release xt if needed
            int256 finalXtReserve = xtReserve.toInt256() + deltaXt;
            if (finalXtReserve < 0) {
                _releaseLiquidity(ITermMaxOrder(orderAddress), asset, uint256(-finalXtReserve));
            }
        } else {
            ftChanges = uint256(-deltaFt) * Constants.DECIMAL_BASE_SQ;
            _totalFt -= ftChanges;
            uint256 deltaAnnualizedInterest = (ftChanges * 365 days) / (maturity - block.timestamp);
            uint256 maturityInterest = _maturityToInterest[maturity.toUint64()];
            if (maturityInterest < deltaAnnualizedInterest || _annualizedInterest < deltaAnnualizedInterest) {
                revert VaultErrors.OrderHasNegativeInterest();
            }
            _maturityToInterest[uint64(maturity)] = maturityInterest - deltaAnnualizedInterest;
            _annualizedInterest -= deltaAnnualizedInterest;
            _checkApy();

            /// @dev Make sure that the interest of order does not go negative
            int256 finalFtReserve = ftReserve.toInt256() + deltaFt;
            int256 finalXtReserve = xtReserve.toInt256() + deltaXt;
            if (finalFtReserve < finalXtReserve) {
                revert VaultErrors.OrderHasNegativeInterest();
            }
        }
        /// @dev Ensure that the total assets after the transaction are
        /// greater than or equal to the principal and the allocated interest
        _checkLockedFt();
    }

function dealBadDebt(address collateral, uint256 badDebtAmt, address recipient, address owner)
        external
        virtual
        nonReentrant
        returns (uint256 shares, uint256 collateralOut)
    {
        if (collateral == asset()) revert VaultErrorsV2.CollateralIsAsset();
        shares = previewWithdraw(badDebtAmt);
        uint256 maxShares = maxRedeem(owner);
        if (shares > maxShares) {
            revert ERC4626ExceededMaxRedeem(recipient, shares, maxShares);
        }

        if (msg.sender != owner) {
            _spendAllowance(owner, msg.sender, shares);
        }

        _burn(owner, shares);

        collateralOut = abi.decode(
            _delegateCall(abi.encodeCall(IOrderManager.dealBadDebt, (recipient, collateral, badDebtAmt))), (uint256)
        );

        emit VaultEvents.DealBadDebt(msg.sender, recipient, collateral, badDebtAmt, shares, collateralOut);
    }

function dealBadDebt(address recipient, address collateral, uint256 amount)
        external
        onlyProxy
        returns (uint256 collateralOut)
    {
        _accruedInterest();
        uint256 badDebtAmt = _badDebtMapping[collateral];
        require(badDebtAmt != 0, VaultErrors.NoBadDebt(collateral));
        require(amount <= badDebtAmt, VaultErrors.InsufficientFunds(badDebtAmt, amount));
        uint256 collateralBalance = IERC20(collateral).balanceOf(address(this));
        collateralOut = (amount * collateralBalance) / badDebtAmt;
        IERC20(collateral).safeTransfer(recipient, collateralOut);

        _badDebtMapping[collateral] -= amount;
        uint256 amplifiedAmt = amount * Constants.DECIMAL_BASE_SQ;
        _accretingPrincipal -= amplifiedAmt;
        _totalFt -= amplifiedAmt;
    }

function depositAssets(IERC20 asset, uint256 amount) external onlyProxy {
        _accruedInterest();
        // deposit to lpers
        uint256 amplifiedAmt = amount * Constants.DECIMAL_BASE_SQ;
        _totalFt += amplifiedAmt;
        _accretingPrincipal += amplifiedAmt;
        _depositToPoolOrNot(asset, amount);
    }

function redeemOrder(ITermMaxOrderV2 order)
        external
        virtual
        nonReentrant
        onlyCuratorRole
        whenNotPaused
        returns (uint256 badDebt, uint256 deliveryCollateral)
    {
        bytes memory returnData =
            _delegateCall(abi.encodeCall(IOrderManagerV2.redeemOrder, (IERC20(asset()), address(order))));
        (badDebt, deliveryCollateral) = abi.decode(returnData, (uint256, uint256));
    }

function redeemOrder(IERC20 asset, address order)
        external
        onlyProxy
        returns (uint256 badDebt, uint256 deliveryCollateral)
    {
        _checkOrder(order);
        bytes memory deliveryData;
        (badDebt, deliveryData) = ITermMaxOrderV2(order).redeemAll(address(this));
        deliveryCollateral = deliveryData.length == 0 ? 0 : abi.decode(deliveryData, (uint256));
        if (badDebt != 0) {
            // store bad debt
            ITermMaxMarket market = ITermMaxOrder(order).market();
            (,,, address collateral,) = market.tokens();
            _badDebtMapping[collateral] += badDebt;
        }
        _depositToPoolOrNot(asset, asset.balanceOf(address(this)));

        delete _orderMaturityMapping[order];
        emit VaultEventsV2.RedeemOrder(msg.sender, order, badDebt, deliveryCollateral);
    }

function removeLiquidityFromOrders(address[] memory orders, uint256[] memory removedLiquidities)
        external
        virtual
        nonReentrant
        onlyCuratorRole
    {
        _delegateCall(
            abi.encodeCall(IOrderManagerV2.removeLiquidityFromOrders, (IERC20(asset()), orders, removedLiquidities))
        );
    }

function removeLiquidityFromOrders(IERC20 asset, address[] memory orders, uint256[] memory removedLiquidities)
        external
        onlyProxy
    {
        require(orders.length == removedLiquidities.length, VaultErrorsV2.ArrayLengthMismatch());
        _accruedInterest();
        uint256 totalRemovingLiquidity;
        for (uint256 i = 0; i < orders.length; ++i) {
            address order = orders[i];
            uint256 removingLiquidity = removedLiquidities[i];
            _checkOrder(order);
            if (removingLiquidity != 0) {
                ITermMaxOrderV2(order).removeLiquidity(asset, removingLiquidity, address(this));
                totalRemovingLiquidity += removingLiquidity;
            }
        }
        if (totalRemovingLiquidity != 0) {
            _depositToPoolOrNot(asset, totalRemovingLiquidity);
        }
        emit VaultEventsV2.OrdersLiquidityRemoved(msg.sender, orders, removedLiquidities);
    }

function withdrawAssets(IERC20 asset, address recipient, uint256 amount) external onlyProxy {
        _reduceAssets(amount);
        _withdrawFromPoolOrNot(asset, recipient, amount);
    }

function withdrawFts(address order, uint256 amount, address recipient, address owner)
        external
        virtual
        nonReentrant
        returns (uint256 shares)
    {
        shares = previewWithdraw(amount);
        uint256 maxShares = maxRedeem(owner);
        if (shares > maxShares) {
            revert ERC4626ExceededMaxRedeem(owner, shares, maxShares);
        }
        if (msg.sender != owner) {
            _spendAllowance(owner, msg.sender, shares);
        }

        _delegateCall(abi.encodeCall(IOrderManagerV2.withdrawFts, (order, amount, recipient)));
        _burn(owner, shares);

        emit VaultEventsV2.WithdrawFts(msg.sender, recipient, order, amount, shares);
    }

function withdrawFts(address order, uint256 amount, address recipient) external onlyProxy {
        _checkOrder(order);
        _reduceAssets(amount);

        ITermMaxMarket market = ITermMaxOrder(order).market();
        (IERC20 ft,,,,) = market.tokens();
        ITermMaxOrder(order).withdrawAssets(ft, recipient, amount);
    }

