        amounts = getAmountsIn(amountOut, params.path, params.factories, params.gt3Factory);
        if (amounts[0] > msgValue) revert IRouter.RouterExcesiveInputAmount(amounts[0], msgValue);
        IWETH(params.weth).deposit{value: amounts[0]}();
        assert(
